package com.shms.controller;
import com.shms.entity.User;import com.shms.repository.InvoiceRepository;import com.shms.repository.DoctorRepository;import com.shms.repository.PatientRepository;import jakarta.servlet.http.HttpSession;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.GetMapping;
@Controller public class ReceptionController{private final DoctorRepository doctors;private final PatientRepository patients;private final InvoiceRepository bills;public ReceptionController(DoctorRepository d,PatientRepository p,InvoiceRepository b){doctors=d;patients=p;bills=b;}@GetMapping("/reception-dashboard")public String dashboard(HttpSession s,Model m){Object o=s.getAttribute("currentUser");if(!(o instanceof User u)||!"RECEPTIONIST".equals(u.getRole()))return "redirect:/login";m.addAttribute("user",u);m.addAttribute("doctorsCount",doctors.count());m.addAttribute("patientsCount",patients.count());m.addAttribute("billsCount",bills.count());return "reception-dashboard";}}
